import { syncSelection, syncPeriod } from "./tableDefs/streamingExport";
export { syncSelection } from "./tableDefs/streamingExport";
import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";
import deploymentAuditLogTable, {
  systemStopState,
} from "./tableDefs/deploymentAuditLogTable";
import { snapshotImportsTable } from "./tableDefs/snapshotImport";
import { awsLambdaVersionsTable } from "./tableDefs/awsLambdaVersions";

// This file isn't autogenerated, it must be manually synced with system tables.

export const udfType = v.union(
  v.literal("Query"),
  v.literal("Mutation"),
  v.literal("Action"),
  v.literal("HttpAction"),
);

const schemaState = v.union(
  v.literal("pending"),
  v.literal("validated"),
  v.literal("active"),
  v.literal("failed"),
  v.literal("overwritten"),
);

const schemaMetadata = v.object({
  state: v.object({ state: schemaState, error: v.optional(v.string()) }),
  // This is a string because the rust code serializes the DatabaseSchema structure to a string.
  schema: v.optional(v.string()),
});

export const udfVisibility = v.union(
  v.object({ kind: v.literal("public") }),
  v.object({ kind: v.literal("internal") }),
);

const analyzedSourcePosition = v.object({
  path: v.string(),
  start_lineno: v.int64(),
  start_col: v.int64(),
});

const analyzedFunction = v.object({
  name: v.string(),
  // Exactly one of these two will be defined
  lineno: v.optional(v.int64()),
  pos: v.optional(analyzedSourcePosition),
  udfType,
  visibility: v.optional(v.union(v.null(), udfVisibility)),
  args: v.optional(v.string()),
  returns: v.union(v.string(), v.null()),
});

const analyzedHttpRoute = v.object({
  route: v.object({
    path: v.string(),
    method: v.string(),
  }),
  // Exactly one of the two will be defined
  lineno: v.optional(v.int64()),
  pos: v.optional(analyzedSourcePosition),
});

const CronSchedule = v.union(
  v.object({
    type: v.literal("interval"),
    seconds: v.int64(),
  }),
  v.object({
    type: v.literal("hourly"),
    minuteUTC: v.optional(v.int64()),
  }),
  v.object({
    type: v.literal("daily"),
    minuteUTC: v.optional(v.int64()),
    hourUTC: v.int64(),
  }),
  v.object({
    type: v.literal("weekly"),
    dayOfWeek: v.int64(),
    hourUTC: v.int64(),
    minuteUTC: v.optional(v.int64()),
  }),
  v.object({
    type: v.literal("monthly"),
    day: v.int64(),
    minuteUTC: v.optional(v.int64()),
    hourUTC: v.int64(),
  }),
  v.object({
    type: v.literal("cron"),
    cronExpr: v.string(),
  }),
);

const analyzedCronSpec = v.object({
  udfPath: v.string(),
  udfArgs: v.bytes(),
  cronSchedule: CronSchedule,
});

const mappedModule = v.object({
  sourceIndex: v.union(v.int64(), v.null()),
  functions: v.array(analyzedFunction),
  httpRoutes: v.union(v.array(analyzedHttpRoute), v.null()),
  cronSpecs: v.optional(
    v.union(
      v.array(
        v.object({
          identifier: v.string(),
          spec: analyzedCronSpec,
        }),
      ),
      v.null(),
    ),
  ),
});

const analyzedModule = v.object({
  functions: v.array(analyzedFunction),
  httpRoutes: v.union(v.array(analyzedHttpRoute), v.null()),
  cronSpecs: v.optional(
    v.union(
      v.array(
        v.object({
          identifier: v.string(),
          spec: analyzedCronSpec,
        }),
      ),
      v.null(),
    ),
  ),
  sourceMapped: v.union(mappedModule, v.null()),
});

const exportRequestor = v.union(
  v.literal("snapshotExport"),
  v.literal("cloudBackup"),
);

export const completedExport = v.object({
  state: v.literal("completed"),
  complete_ts: v.int64(),
  expiration_ts: v.int64(),
  start_ts: v.int64(),
  tables: v.optional(v.array(v.array(v.string()))),
  zip_object_key: v.optional(v.string()),
  format: v.optional(
    v.object({
      format: v.literal("zip"),
      include_storage: v.boolean(),
    }),
  ),
  requestor: exportRequestor,
});

const cronJobStatus = v.union(
  v.object({
    type: v.literal("success"),
    result: v.any(),
  }),
  v.object({
    type: v.literal("err"),
    error: v.any(),
  }),
  v.object({
    type: v.literal("canceled"),
    num_canceled: v.int64(),
  }),
);

// Log sinks
export const sinkState = v.union(
  v.object({
    type: v.literal("pending"),
  }),
  v.object({
    type: v.literal("failed"),
    reason: v.string(),
  }),
  v.object({
    type: v.literal("active"),
  }),
  v.object({
    type: v.literal("deleting"),
  }),
);

// The subscribable log stream topics.
export const logTopic = v.union(
  v.literal("console"),
  v.literal("function_execution"),
  v.literal("audit_log"),
  v.literal("scheduler_stats"),
  v.literal("scheduled_job_lag"),
  v.literal("current_storage_usage"),
  v.literal("concurrency_stats"),
  v.literal("storage_api_bandwidth"),
  v.literal("ai_gateway_usage"),
  v.literal("log_stream_egress"),
  v.literal("custom_audit"),
);

// The topics a log stream is subscribed to. Absent means subscribed to all
// topics, including ones added in the future.
const subscribedTopics = v.optional(v.array(logTopic));

export const datadogConfig = v.object({
  type: v.literal("datadog"),
  siteLocation: v.union(
    v.literal("US1"),
    v.literal("US3"),
    v.literal("US5"),
    v.literal("EU"),
    v.literal("US1_FED"),
    v.literal("AP1"),
  ),
  ddApiKey: v.string(),
  ddTags: v.array(v.string()),
  service: v.optional(v.string()),
  version: v.optional(v.union(v.literal("1"), v.literal("2"))),
  topics: subscribedTopics,
});

export const webhookConfig = v.object({
  type: v.literal("webhook"),
  url: v.string(),
  format: v.union(v.literal("json"), v.literal("jsonl")),
  hmacSecret: v.string(),
  topics: subscribedTopics,
});

export const axiomConfig = v.object({
  type: v.literal("axiom"),
  apiKey: v.string(),
  datasetName: v.string(),
  attributes: v.array(
    v.object({
      key: v.string(),
      value: v.string(),
    }),
  ),
  version: v.optional(v.union(v.literal("1"), v.literal("2"))),
  ingestUrl: v.optional(v.string()),
  topics: subscribedTopics,
});

export const sentryConfig = v.object({
  type: v.literal("sentry"),
  dsn: v.string(),
  tags: v.optional(v.record(v.string(), v.string())),
  version: v.optional(v.union(v.literal("1"), v.literal("2"))),
});

export const postHogLogsConfig = v.object({
  type: v.literal("postHogLogs"),
  apiKey: v.string(),
  host: v.optional(v.string()),
  serviceName: v.optional(v.string()),
  topics: subscribedTopics,
});

export const postHogErrorTrackingConfig = v.object({
  type: v.literal("postHogErrorTracking"),
  apiKey: v.string(),
  host: v.optional(v.string()),
});

const s3ExportProgress = v.union(
  v.object({
    type: v.literal("snapshotting"),
    numTablesSynced: v.int64(),
    totalTables: v.int64(),
    currentComponent: v.string(),
    currentTable: v.string(),
    numDocumentsInCurrentTable: v.int64(),
    totalDocumentsInCurrentTable: v.union(v.int64(), v.null()),
    numDocumentsSynced: v.int64(),
    totalDocuments: v.union(v.int64(), v.null()),
  }),
  v.object({ type: v.literal("stale"), ts: v.int64() }),
  v.object({ type: v.literal("upToDate"), ts: v.int64() }),
);

export const s3ExportConfig = v.object({
  type: v.literal("s3Export"),
  bucket: v.string(),
  region: v.string(),
  prefix: v.optional(v.string()),
  accessKeyId: v.optional(v.string()),
  secretAccessKey: v.optional(v.string()),
  // Empty until the admin pastes the ARN from their CloudFormation stack.
  roleArn: v.optional(v.string()),
  roleExternalId: v.optional(v.string()),
  selection: syncSelection,
  period: syncPeriod,
});

export const sinkConfig = v.union(
  datadogConfig,
  webhookConfig,
  axiomConfig,
  sentryConfig,
  postHogLogsConfig,
  postHogErrorTrackingConfig,
  s3ExportConfig,
);

const logSinksTable = defineTable({
  status: sinkState,
  config: sinkConfig,
});

const userStopState = v.union(v.literal("none"), v.literal("paused"));

const usageLimitStopState = v.union(v.literal("none"), v.literal("disabled"));

export const backendState = v.object({
  system: systemStopState,
  usage_limit: usageLimitStopState,
  user: userStopState,
});

const backendStateTable = defineTable(backendState);

export const cronJobState = v.union(
  v.object({ type: v.literal("pending") }),
  v.object({ type: v.literal("inProgress") }),
);

export default defineSchema({
  _tables: defineTable({
    name: v.string(),
    state: v.union(
      v.literal("active"),
      v.literal("deleting"),
      v.literal("hidden"),
    ),
    namespace: v.optional(
      v.object({
        kind: v.literal("byComponent"),
        id: v.string(),
      }),
    ),
  }).index("by_name", ["name"]),
  _index: defineTable({
    table_id: v.string(),
    descriptor: v.string(),
    config: v.union(
      v.object({
        type: v.literal("database"),
        fields: v.array(v.string()),
        onDiskState: v.union(
          v.object({
            type: v.literal("Backfilling"),
            backfillState: v.object({
              staged: v.optional(v.boolean()),
            }),
          }),
          v.object({
            type: v.literal("Backfilled2"),
            staged: v.optional(v.boolean()),
          }),
          v.object({
            type: v.literal("Enabled"),
          }),
          v.object({
            type: v.literal("Disabled"),
          }),
        ),
      }),
      v.object({
        type: v.literal("search"),
        searchField: v.string(),
        filterFields: v.array(v.string()),
        onDiskState: v.union(
          v.object({
            state: v.union(
              v.literal("backfilling"),
              v.literal("backfilling2"),
              v.literal("backfilled2"),
            ),
            // skip some fields here
            staged: v.optional(v.boolean()),
          }),
          v.object({
            state: v.union(v.literal("backfilled"), v.literal("snapshotted")),
          }),
        ),
      }),
      v.object({
        type: v.literal("vector"),
        vectorField: v.string(),
        dimensions: v.int64(),
        filterFields: v.array(v.string()),
        onDiskState: v.union(
          v.object({
            state: v.union(
              v.literal("backfilling"),
              v.literal("backfilled"),
              v.literal("backfilled2"),
            ),
            staged: v.optional(v.boolean()),
          }),
          v.object({ state: v.literal("snapshotted") }),
        ),
      }),
    ),
  }),
  _index_backfills: defineTable({
    indexId: v.id("_index"),
    numDocsIndexed: v.int64(),
    totalDocs: v.union(v.int64(), v.null()),
  }).index("by_index_id", ["indexId"]),
  _components: defineTable({
    definitionId: v.id("_component_definitions"),
    parent: v.union(v.id("_components"), v.null()),
    name: v.union(v.string(), v.null()),
    args: v.union(v.array(v.any()), v.null()),
    state: v.optional(v.union(v.literal("active"), v.literal("unmounted"))),
    // Absolute path this component's HTTP routes are served under: the app's
    // `httpPrefix` for the root, the mount path in the parent for children.
    httpPrefix: v.optional(v.union(v.string(), v.null())),
  }),
  _modules: defineTable({
    path: v.string(),
    latestVersion: v.int64(),
    deleted: v.boolean(),
    analyzeResult: v.union(analyzedModule, v.null()),
    sourcePackageId: v.string(),
    environment: v.union(
      v.literal("node"),
      v.literal("isolate"),
      v.literal("invalid"),
    ),
  }).index("by_path", ["path"]),
  _auth: defineTable(
    v.union(
      v.object({
        type: v.literal("customJwt"),
        applicationID: v.union(v.string(), v.null()),
        issuer: v.string(),
        jwks: v.string(),
        // This is serialized *wrapped with double quotes* (!)
        algorithm: v.string(),
      }),
      v.object({
        applicationID: v.string(),
        domain: v.string(),
      }),
    ),
  ),
  _environment_variables: defineTable({
    name: v.string(),
    value: v.string(),
  }).index("by_name", ["name"]),
  _exports: defineTable(
    v.union(
      completedExport,
      v.object({
        // "failed" state is unused for new exports, because there are no
        // developer-error failure scenarios, so the export is retried until
        // success.
        state: v.literal("failed"),
        start_ts: v.int64(),
        failed_ts: v.int64(),
        requestor: exportRequestor,
      }),
      v.object({
        state: v.literal("in_progress"),
        start_ts: v.int64(),
        requestor: exportRequestor,
        progress_message: v.optional(v.union(v.null(), v.string())),
      }),
      v.object({
        state: v.literal("requested"),
        requestor: exportRequestor,
      }),
      v.object({
        state: v.literal("canceled"),
        start_ts: v.optional(v.union(v.null(), v.int64())),
        canceled_ts: v.int64(),
        requestor: exportRequestor,
      }),
    ),
  ).index("by_requestor", ["requestor"]),
  _deployment_audit_log: deploymentAuditLogTable,
  _scheduled_jobs: defineTable({
    nextTs: v.union(v.int64(), v.null()),
    udfPath: v.string(),
    state: v.union(
      v.object({ type: v.literal("pending") }),
      v.object({ type: v.literal("inProgress") }),
    ),
    udfArgs: v.nullable(v.bytes()),
    argsId: v.nullable(v.id("_scheduled_job_args")),
    component: v.optional(v.string()),
  })
    .index("by_udf_path_and_next_event_ts", ["udfPath", "nextTs"])
    .index("by_next_ts", ["nextTs"]),
  _scheduled_job_args: defineTable({
    args: v.bytes(),
  }),
  _cron_jobs: defineTable({
    name: v.string(),
    cronSpec: analyzedCronSpec,
  }).index("by_name", ["name"]),
  _cron_next_run: defineTable({
    cronJobId: v.id("_cron_jobs"),
    state: cronJobState,
    prevTs: v.union(v.int64(), v.null()),
    nextTs: v.int64(),
  })
    .index("by_cron_job_id", ["cronJobId"])
    .index("by_next_ts", ["nextTs"]),
  _cron_job_logs: defineTable({
    name: v.string(),
    ts: v.int64(),
    udfPath: v.string(),
    udfArgs: v.bytes(),
    status: cronJobStatus,
    logLines: v.object({
      logLines: v.array(v.string()),
      isTruncated: v.boolean(),
    }),
    executionTime: v.number(),
  }).index("by_name_and_ts", ["name", "ts"]),
  _udf_config: defineTable({ serverVersion: v.string() }),
  _schemas: defineTable(schemaMetadata).index("by_state", ["state"]),
  _schema_validations: defineTable({
    schemaId: v.id("_schemas"),
    tableName: v.string(),
    validatorHash: v.optional(v.string()),
    state: v.union(
      v.object({ state: v.literal("pending") }),
      v.object({ state: v.literal("valid") }),
      v.object({ state: v.literal("failed"), error: v.string() }),
    ),
  }).index("by_schema_id_and_table_name", ["schemaId", "tableName"]),
  _schema_validation_progress: defineTable({
    validationId: v.id("_schema_validations"),
    numDocsValidated: v.int64(),
    totalDocs: v.union(v.int64(), v.null()),
  }).index("by_validation_id", ["validationId"]),
  _log_sinks: logSinksTable,
  _s3_export_state: defineTable({
    configId: v.id("_log_sinks"),
    checkpoint: v.object({
      progress: s3ExportProgress,
    }),
  }).index("by_config_id", ["configId"]),
  _backend_state: backendStateTable,
  _snapshot_imports: snapshotImportsTable,
  _aws_lambda_versions: awsLambdaVersionsTable,
  _backend_info: defineTable({
    auditLogRetentionDays: v.union(v.int64(), v.null()),
  }),
});
